package brackets

import "testing"

func TestIsBalancedValid(t *testing.T) {
	for _, s := range []string{"()", "()[]{}", "{[()]}", ""} {
		if !IsBalanced(s) {
			t.Fatalf("%q should be balanced", s)
		}
	}
}

func TestIsBalancedInvalid(t *testing.T) {
	for _, s := range []string{"(", ")", "([)]", "{[}"} {
		if IsBalanced(s) {
			t.Fatalf("%q should not be balanced", s)
		}
	}
}

func TestMinInsertionsBasic(t *testing.T) {
	// "(" needs 1 closing
	if got := MinInsertions("("); got != 1 {
		t.Fatalf("want 1 got %d", got)
	}
	// ")" needs 1 opening
	if got := MinInsertions(")"); got != 1 {
		t.Fatalf("want 1 got %d", got)
	}
}

func TestMinInsertionsComplex(t *testing.T) {
	// "(()" needs 1 closing
	if got := MinInsertions("(()"); got != 1 {
		t.Fatalf("want 1 got %d", got)
	}
	// ")))" needs 3 openings
	if got := MinInsertions(")))"); got != 3 {
		t.Fatalf("want 3 got %d", got)
	}
}

func TestMinInsertionsAlreadyBalanced(t *testing.T) {
	if got := MinInsertions("()"); got != 0 {
		t.Fatalf("want 0 got %d", got)
	}
	if got := MinInsertions(""); got != 0 {
		t.Fatalf("want 0 got %d", got)
	}
}

