  // For '(', '[', '{': push onto stack.
  // For ')', ']', '}': if stack empty or top doesn't match, return false; else pop.
  // Return true if stack is empty at end.

func MinInsertions(s string) int
  // Only handles '(' and ')' (parentheses only).
  // Track open count (unmatched '(') and insertions needed.
  // For '(': open++.
  // For ')': if open > 0, open-- (match found); else insertions++ (need '(' inserted).
  // At end: insertions += open (unmatched '(' each need a ')').
  // Return insertions.

